          await completer.operation.valueOrCancellation();
          final operation = CancelableCompleter<void>(
            onCancel: expectAsync0(() {}, count: 0),
          ).operation;
          completer.completeOperation(operation, propagateCancel: false);
        },
      );
    });
  });

