    var st3 = c.stream;
    testZip(
      [st1, st2, st3],
      [
        [1, 4, 7],
        [2, 5, 8],
        [3, 6, 9],
      ],
    );
    c
      ..add(7)
      ..add(8)
      ..add(9)
      ..close();
  });

  test('Error 1', () {
    expect(
      StreamZip([
        streamError(mks([1, 2, 3]), 2, 'BAD-1'),
        mks([4, 5, 6]),
        mks([7, 8, 9]),
      ]).toList(),
